def strip_unnamed(string: str) -> str:
    """When fusing headers coming from excel, the lines with NA values are
    named as `Unnamed:...`. This function filters them out.
    """
    if string.strip().startswith("Unnamed:"):
        return ""
    else:
        return string.strip()

